defined('ABSPATH') || exit;
?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><?php wp_head(); ?></head><body <?php body_class('barad-site'); ?> data-design="<?php echo esc_attr(get_option('barad_design','blueprint')); ?>"><?php wp_body_open(); echo barad_header(); ?><main id="main-content">
<?php $term=get_queried_object();$children=barad_catalog_terms($term->term_id); ?>
<section class="subhero w"><?php echo barad_breadcrumb_html(); ?><div class="barad-collection-header"><div class="barad-collection-copy"><span class="barad-collection-kicker"><?php echo esc_html(barad_t('کاتالوگ باراد')); ?></span><h1><?php single_term_title(); ?></h1><p><?php echo esc_html($term->description); ?></p><?php if(isset(barad_afshar_groups()[barad_source_term($term,'product_cat')->slug])){ ?><p class="barad-collection-brand"><?php echo esc_html(barad_t('باراد نمایندهٔ رسمی افشارنژاد خراسان است. ')); ?><a href="<?php echo esc_url(barad_url('afsharnejad')); ?>"><?php echo esc_html(barad_t('معرفی برند و استعلام قیمت ←')); ?></a></p><?php } ?><div class="barad-collection-facts"><span><?php global $wp_query; echo esc_html(number_format_i18n($wp_query->found_posts)); ?> <?php echo esc_html(barad_t('کالا در این دسته')); ?></span><span><?php echo esc_html(barad_t('مشخصات فنی و سایزها')); ?></span></div></div><?php echo barad_catalog_visual(); ?></div><div class="barad-collection-tools"><?php echo barad_catalog_search_form(); ?></div></section>
<section class="section w barad-product-collection"><?php echo barad_catalog_sibling_links($term); ?><?php if($children){ ?><div class="section-title"><h2><?php echo esc_html(barad_t('زیردسته‌ها')); ?></h2><a href="<?php echo esc_url(barad_url('catalog')); ?>"><?php echo esc_html(barad_t('همهٔ دسته‌بندی‌ها ←')); ?></a></div><?php echo barad_catalog_category_cards($children); ?><?php }else{ ?><div class="catalog-toolbar"><span><?php global $wp_query; echo esc_html(number_format_i18n($wp_query->found_posts)); ?> <?php echo esc_html(barad_t('کالا')); ?></span><a href="<?php echo esc_url(barad_url('catalog')); ?>"><?php echo esc_html(barad_t('همهٔ دسته‌بندی‌ها ←')); ?></a><?php echo barad_catalog_view_controls(); ?></div><div class="products" id="barad-catalog"><?php while(have_posts()) { the_post(); echo barad_card(wc_get_product(get_the_ID())); }if(!$wp_query->found_posts)echo '<p class="empty">'.esc_html(barad_t('در این دسته هنوز کالایی ثبت نشده است.')).'</p>'; ?></div><nav class="barad-pagination" aria-label="<?php echo esc_attr(barad_t('صفحه‌های کالاها')); ?>"><?php echo wp_kses_post(paginate_links(['total'=>$wp_query->max_num_pages,'current'=>max(1,get_query_var('paged'))]) ?: ''); ?></nav><?php } ?></section>
